effect.shader:
float gmHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
void main(){
  vec2 baseUv = acScreenNorm;
  vec4 origin = texture2DCv(inputImg.texture, baseUv);
  float t = floor(acTime * speed);
  vec2 uv = baseUv;
  float track = gmHash(vec2(floor(baseUv.y * 18.0), t));
  float active = step(1.0 - tears, track);
  uv.x += sin(baseUv.y * 78.0 + acTime * speed) * wobble * mixAmt;
  uv.x += (gmHash(vec2(floor(baseUv.y * 18.0) * 3.1, t + 8.0)) - 0.5) * 0.13 * tears * active * mixAmt;
  float r = texture2DCv(inputImg.texture, uv + vec2(bleed, 0.0)).r / max(texture2DCv(inputImg.texture, uv + vec2(bleed, 0.0)).a, 1e-4);
  vec4 mid = texture2DCv(inputImg.texture, uv);
  float g = mid.g / max(mid.a, 1e-4);
  float b = texture2DCv(inputImg.texture, uv - vec2(bleed, 0.0)).b / max(texture2DCv(inputImg.texture, uv - vec2(bleed, 0.0)).a, 1e-4);
  vec3 c = vec3(r, g, b);
  float grain = gmHash(floor(baseUv * acScreenSize) + floor(acTime * 60.0));
  c += (grain - 0.5) * noise * mixAmt;
  float scan = 1.0 - 0.13 * (0.5 + 0.5 * sin(baseUv.y * acScreenSize.y * 3.1415926));
  c *= scan;
  c *= 1.0 - active * 0.34;
  float l = gmLum(c);
  c = mix(c, vec3(l), 0.10);
  vec3 col = mix(origin.rgb / max(origin.a, 1e-4), c, mixAmt);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * origin.a, origin.a);
}
